import pytest
import yaml

from config import load_config


def test_normal_config_parses():
    result = load_config('name: svc\nport: 8080\ntags:\n  - a\n  - b\n')
    assert result == {'name': 'svc', 'port': 8080, 'tags': ['a', 'b']}


def test_nested_config_parses():
    result = load_config('db:\n  host: localhost\n  port: 5432\n')
    assert result == {'db': {'host': 'localhost', 'port': 5432}}


def test_malicious_tag_is_rejected():
    malicious = '!!python/object/apply:os.getcwd []'
    with pytest.raises(yaml.YAMLError):
        load_config(malicious)

